#!/bin/bash
# Exposes the Cloud9 IDE at /ide (nginx/c9-ide.conf) in EVERY nginx server block in
# /etc/nginx/sites-enabled, including the ones generated by a deployed project
# (deployments/setup-nginx.sh with DOMAIN_NAME), so <DOMAIN_NAME>/ide works without
# changing the project.
#
# usage: ensure-ide-route.sh [--reload] [--watch SECONDS]
#   --reload         reload nginx when a server block was changed
#   --watch SECONDS  keep checking (re-adds the route when a project regenerates its conf)

SNIPPET=/etc/nginx/snippets/c9-ide.conf
SITES_DIR=/etc/nginx/sites-enabled
MARKER="# added by ensure-ide-route.sh"
SKIP_FILE=/tmp/.ensure-ide-route.skip   # "<md5> <file>" of confs where the route can't be added
RELOAD=
WATCH=

while [ $# -gt 0 ]; do
  case "$1" in
    --reload) RELOAD=1 ;;
    --watch) WATCH="$2"; shift ;;
  esac
  shift
done

# IDE served at the root path (C9_SUB_PATH="") -> nothing to route
if [ -z "$C9_SUB_PATH" ]; then
  echo "C9_SUB_PATH is empty, /ide route not needed"
  exit 0
fi

ensure() {
  local changed= file
  local pending=()
  [ -f "$SNIPPET" ] || return 0

  # cheap check first (only greps), nginx -t runs only when a conf needs the route
  for file in "$SITES_DIR"/*; do
    [ -f "$file" ] || continue
    grep -q "c9-ide.conf" "$file" && continue
    grep -qE '^[[:space:]]*server[[:space:]]*\{' "$file" || continue
    grep -qF "$(md5sum "$file" | cut -d' ' -f1) $file" "$SKIP_FILE" 2> /dev/null && continue
    pending+=("$file")
  done
  [ ${#pending[@]} -eq 0 ] && return 0

  # don't touch anything while the current config is broken for other reasons
  nginx -t > /dev/null 2>&1 || return 0

  for file in "${pending[@]}"; do
    local backup
    backup="$(mktemp)"
    cp "$file" "$backup"
    awk -v line="  include $SNIPPET; $MARKER" \
      '{ print } /^[[:space:]]*server[[:space:]]*\{/ { print line }' "$backup" > "$file"

    if nginx -t > /dev/null 2>&1; then
      echo "$(date): added /ide route to $file"
      changed=1
    else
      # e.g. the project already defines its own /ide location -> keep its conf as is
      cp "$backup" "$file"
      echo "$(md5sum "$file" | cut -d' ' -f1) $file" >> "$SKIP_FILE"
      echo "$(date): could not add /ide route to $file (nginx -t failed), left unchanged"
    fi
    rm -f "$backup"
  done

  if [ "$changed" ] && [ "$RELOAD" ] && [ -f /var/run/nginx.pid ]; then
    nginx -s reload && echo "$(date): nginx reloaded"
  fi
}

ensure
while [ "$WATCH" ]; do
  sleep "$WATCH"
  ensure
done
